const metrics = $('Get Yesterday Metrics').item.json;
const summary = $('AI Summarize Alerts').item.json;

const sales = metrics.sales || [];
const totalRevenue = sales.reduce((sum, s) => sum + (s.revenue_brl || 0), 0);
const totalOrders = sales.reduce((sum, s) => sum + (s.orders_count || 0), 0);
const avgTicket = totalOrders > 0 ? totalRevenue / totalOrders : 0;

const aiSummary = summary.summary || {};
const alertsAnalyzed = summary.alerts_analyzed || 0;

const today = new Date().toLocaleDateString('pt-BR', { 
  weekday: 'long', 
  day: '2-digit', 
  month: 'long',
  timeZone: 'America/Sao_Paulo'
});

const report = `📊 *RELATÓRIO DIÁRIO — Saint Germain*
_${today}_

💰 *Faturamento ontem:* R$${totalRevenue.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
📦 *Pedidos:* ${totalOrders}
🎯 *Ticket médio:* R$${avgTicket.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}

🤖 *Análise IA:*
${aiSummary.executive_summary || 'Sem análise disponível.'}

${aiSummary.critical_actions && aiSummary.critical_actions.length > 0 ? 
  '⚡ *Ações prioritárias:*\n' + aiSummary.critical_actions.map((a, i) => `${i+1}. ${a}`).join('\n') 
  : ''}

📈 *Status geral:* ${aiSummary.overall_status || 'Normal'}
🔔 *Alertas analisados:* ${alertsAnalyzed}

_Central Operacional SG_`;

return [{ json: { report, metrics: { totalRevenue, totalOrders, avgTicket }, status: aiSummary.overall_status } }];

const result = $input.first().json;
const report = $('Format Report').item.json;

console.log('Daily report sent:', result);
console.log('Revenue:', report.metrics.totalRevenue);
console.log('Orders:', report.metrics.totalOrders);

return [{ json: { 
  success: result.success || false, 
  sent_at: new Date().toISOString(),
  metrics_summary: report.metrics
} }];
